def flag_low_bases(bases: dict[str, float], minimum: float, flags: list[str] = []) -> list[str]:
    """Names of subgroups whose base is below minimum."""
    for name, base in bases.items():
        if base < minimum:
            flags.append(name)
    return flags

exercises.fix_solution:
def flag_low_bases(bases: dict[str, float], minimum: float) -> list[str]:
    """Names of subgroups whose base is below minimum."""
    return [name for name, base in bases.items() if base < minimum]
